const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.1",
  "engineVersion": "55ae170b1ced7fc6ed07a15f110549408c501bb3",
  "activeProvider": "postgresql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// --- 3.1 Core — Users & Auth ---\n\nmodel User {\n  id             String    @id @default(uuid()) @db.Uuid\n  supabaseAuthId String    @unique // Links to Supabase Auth user\n  email          String    @unique\n  username       String    @unique\n  firstName      String?\n  lastName       String?\n  displayName    String?\n  bio            String?   @default(\"\") @db.VarChar(250)\n  avatar         String    @default(\"\")\n  bannerUrl      String    @default(\"\")\n  role           UserRole  @default(USER)\n  gender         Gender?\n  userType       UserType?\n  affiliation    String    @default(\"Other\") @db.VarChar(100)\n  birthMonth     Int?\n  birthDay       Int?\n\n  // Tech profile\n  techCareerPath  String?\n  techStack       String[]        @default([])\n  experienceLevel ExperienceLevel @default(BEGINNER)\n  githubUsername  String?\n  linkedinUrl     String?\n  portfolioUrl    String?\n\n  // Gamification (denormalized for fast reads)\n  points         Int       @default(10)\n  level          Int       @default(1)\n  badges         String[]  @default([])\n  loginStreak    Int       @default(0)\n  lastStreakDate DateTime?\n  isPremium      Boolean   @default(false)\n  isGenerated    Boolean   @default(false) // For bot-created users\n\n  // Referral\n  referralCode String? @unique\n\n  // Counts (denormalized)\n  followersCount Int @default(0)\n  followingCount Int @default(0)\n\n  // Pinned posts (max 3)\n  pinnedPosts String[] @default([]) @db.Uuid\n\n  // Status\n  isVerified          Boolean   @default(false)\n  isBlocked           Boolean   @default(false)\n  onboardingCompleted Boolean   @default(false)\n  lastActive          DateTime  @default(now())\n  lastLogin           DateTime?\n\n  // Location & source\n  location           String?\n  website            String?\n  country            String?\n  interests          String[]           @default([])\n  registrationSource RegistrationSource @default(DIRECT)\n\n  // Settings (JSONB — flexible, not frequently queried)\n  appearanceSettings   Json? @default(\"{}\")\n  privacySettings      Json? @default(\"{}\")\n  notificationSettings Json? @default(\"{}\")\n  pushSubscription     Json?\n\n  // AI usage tracking\n  aiUsage Json? @default(\"{}\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  posts             Post[]\n  comments          Comment[]\n  sentMessages      Message[]      @relation(\"SentMessages\")\n  receivedMessages  Message[]      @relation(\"ReceivedMessages\")\n  projects          Project[]\n  xpLogs            XpLog[]\n  activities        Activity[]\n  notifications     Notification[] @relation(\"RecipientNotifications\")\n  sentNotifications Notification[] @relation(\"SenderNotifications\")\n  likes             Like[]         @relation(\"UserLikes\")\n  mentionsReceived  UserMention[]  @relation(\"MentionedUsers\")\n  mentionsSent      UserMention[]  @relation(\"Mentioners\")\n\n  @@index([points(sort: Desc)])\n  @@index([lastActive(sort: Desc)])\n  @@index([followersCount(sort: Desc)])\n}\n\nmodel Affiliation {\n  id        String   @id @default(uuid()) @db.Uuid\n  category  String // e.g., \"Nigerian_Universities\", \"TechbootCamps\"\n  subType   String // e.g., \"Federal\", \"Private\", \"NIIT_Centres\"\n  name      String   @unique\n  createdAt DateTime @default(now())\n}\n\n// --- 3.2 Social — Posts, Comments, Likes, Follows ---\n\nmodel Post {\n  id          String   @id @default(uuid()) @db.Uuid\n  authorId    String   @db.Uuid\n  communityId String?  @db.Uuid\n  content     String   @default(\"\") @db.Text\n  isAnonymous Boolean  @default(false)\n  imageUrl    String?\n  imageUrls   String[] @default([])\n  videoUrls   String[] @default([])\n\n  // Denormalized counts\n  likesCount    Int @default(0)\n  commentsCount Int @default(0)\n  viewsCount    Int @default(0)\n  xpAwarded     Int @default(20)\n\n  // Status for Admin Governance\n  status PostStatus @default(ACTIVE) // PENDING_REVIEW, ACTIVE, ARCHIVED, BLOCKED\n\n  // SEO\n  slug            String? @unique\n  metaTitle       String?\n  metaDescription String?\n\n  // Media (Improved)\n  media PostMedia[]\n\n  // Poll (JSONB — complex nested structure)\n  poll Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  author    User          @relation(fields: [authorId], references: [id], onDelete: Cascade)\n  community Community?    @relation(fields: [communityId], references: [id])\n  comments  Comment[]\n  // Removed likes relation - now handled polymorphically via targetId\n  tags      PostTag[]\n  mentions  UserMention[]\n  views     View[]\n  auditLogs AuditLog[]    @relation(\"PostAudit\")\n\n  @@index([authorId, createdAt(sort: Desc)])\n  @@index([createdAt(sort: Desc)])\n  @@index([status])\n}\n\nmodel PostMedia {\n  id        String    @id @default(uuid()) @db.Uuid\n  postId    String    @db.Uuid\n  url       String\n  type      MediaType @default(IMAGE)\n  isPrimary Boolean   @default(false)\n  order     Int       @default(0)\n\n  post Post @relation(fields: [postId], references: [id], onDelete: Cascade)\n}\n\nmodel Comment {\n  id         String   @id @default(uuid()) @db.Uuid\n  authorId   String   @db.Uuid\n  postId     String   @db.Uuid\n  parentId   String?  @db.Uuid // Self-referential for threads\n  content    String   @db.VarChar(500)\n  imageUrls  String[] @default([])\n  videoUrls  String[] @default([])\n  likesCount Int      @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  author  User      @relation(fields: [authorId], references: [id], onDelete: Cascade)\n  post    Post      @relation(fields: [postId], references: [id], onDelete: Cascade)\n  parent  Comment?  @relation(\"CommentReplies\", fields: [parentId], references: [id])\n  replies Comment[] @relation(\"CommentReplies\")\n\n  @@index([postId, createdAt(sort: Desc)])\n}\n\nmodel Like {\n  id         String         @id @default(uuid()) @db.Uuid\n  userId     String         @db.Uuid\n  targetId   String         @db.Uuid\n  targetType LikeTargetType\n\n  createdAt DateTime @default(now())\n\n  user User @relation(\"UserLikes\", fields: [userId], references: [id], onDelete: Cascade)\n  // Removed post relation to allow polymorphic behavior (targetId can be Post OR Comment)\n\n  @@unique([userId, targetId, targetType])\n  @@index([targetId, targetType])\n}\n\nmodel Follow {\n  id          String   @id @default(uuid()) @db.Uuid\n  followerId  String   @db.Uuid\n  followingId String   @db.Uuid\n  createdAt   DateTime @default(now())\n\n  @@unique([followerId, followingId])\n  @@index([followerId])\n  @@index([followingId])\n}\n\nmodel Block {\n  id        String      @id @default(uuid()) @db.Uuid\n  blockerId String      @db.Uuid\n  blockedId String      @db.Uuid\n  reason    BlockReason @default(OTHER)\n  createdAt DateTime    @default(now())\n\n  @@unique([blockerId, blockedId])\n}\n\n// --- 3.3 Tags & Mentions ---\n\nmodel Tag {\n  id          String   @id @default(uuid()) @db.Uuid\n  name        String   @unique\n  slug        String   @unique\n  description String?  @db.VarChar(200)\n  color       String   @default(\"#3b82f6\")\n  usageCount  Int      @default(0)\n  isOfficial  Boolean  @default(false)\n  createdById String   @db.Uuid\n  createdAt   DateTime @default(now())\n\n  posts PostTag[]\n\n  @@index([usageCount(sort: Desc)])\n}\n\nmodel PostTag {\n  postId String @db.Uuid\n  tagId  String @db.Uuid\n\n  post Post @relation(fields: [postId], references: [id], onDelete: Cascade)\n  tag  Tag  @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@id([postId, tagId])\n}\n\nmodel UserMention {\n  id          String   @id @default(uuid()) @db.Uuid\n  postId      String   @db.Uuid\n  commentId   String?  @db.Uuid\n  mentionerId String   @db.Uuid\n  mentionedId String   @db.Uuid\n  createdAt   DateTime @default(now())\n\n  post      Post @relation(fields: [postId], references: [id], onDelete: Cascade)\n  mentioner User @relation(\"Mentioners\", fields: [mentionerId], references: [id])\n  mentioned User @relation(\"MentionedUsers\", fields: [mentionedId], references: [id])\n\n  @@index([mentionedId, createdAt(sort: Desc)])\n}\n\n// --- 3.4 Messaging ---\n\nmodel Conversation {\n  id           String   @id @default(uuid()) @db.Uuid\n  lastActivity DateTime @default(now())\n  isArchived   Boolean  @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  participants ConversationParticipant[]\n  messages     Message[]\n\n  @@index([lastActivity(sort: Desc)])\n}\n\nmodel ConversationParticipant {\n  conversationId String   @db.Uuid\n  userId         String   @db.Uuid\n  unreadCount    Int      @default(0)\n  joinedAt       DateTime @default(now())\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@id([conversationId, userId])\n}\n\nmodel Message {\n  id             String      @id @default(uuid()) @db.Uuid\n  conversationId String      @db.Uuid\n  senderId       String      @db.Uuid\n  receiverId     String      @db.Uuid\n  content        String      @db.VarChar(2000)\n  messageType    MessageType @default(TEXT)\n  fileUrl        String?\n  fileName       String?\n  fileSize       Int?\n  replyToId      String?     @db.Uuid\n  isDeleted      Boolean     @default(false)\n  deletedAt      DateTime?\n  read           Boolean     @default(false)\n\n  // Reactions & read receipts as JSONB (variable-length arrays)\n  reactions Json? @default(\"[]\")\n  readBy    Json? @default(\"[]\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  conversation Conversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n  sender       User         @relation(\"SentMessages\", fields: [senderId], references: [id])\n  receiver     User         @relation(\"ReceivedMessages\", fields: [receiverId], references: [id])\n  replyTo      Message?     @relation(\"MessageReplies\", fields: [replyToId], references: [id])\n  replies      Message[]    @relation(\"MessageReplies\")\n\n  @@index([conversationId, createdAt(sort: Desc)])\n  @@index([receiverId, createdAt(sort: Desc)])\n}\n\n// --- 3.5 Communities ---\n\nmodel Community {\n  id          String            @id @default(uuid()) @db.Uuid\n  name        String            @db.VarChar(50)\n  slug        String            @unique\n  description String            @db.VarChar(500)\n  avatar      String?\n  banner      String?\n  category    CommunityCategory\n  tags        String[]          @default([])\n  creatorId   String            @db.Uuid\n  isPrivate   Boolean           @default(false)\n  rules       String[]          @default([])\n\n  // Denormalized counts\n  memberCount Int @default(0)\n  postCount   Int @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  posts   Post[]\n  members CommunityMember[]\n\n  @@index([category])\n  @@index([memberCount(sort: Desc)])\n}\n\nmodel CommunityMember {\n  communityId String              @db.Uuid\n  userId      String              @db.Uuid\n  role        CommunityMemberRole @default(MEMBER)\n  joinedAt    DateTime            @default(now())\n\n  community Community @relation(fields: [communityId], references: [id], onDelete: Cascade)\n\n  @@id([communityId, userId])\n}\n\n// --- 3.6 Gamification ---\n\nmodel XpLog {\n  id       String      @id @default(uuid()) @db.Uuid\n  userId   String      @db.Uuid\n  type     XpEventType\n  xpAmount Float\n  refId    String?     @db.Uuid\n\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt(sort: Desc)])\n  @@index([type, createdAt(sort: Desc)])\n}\n\nmodel UserStats {\n  id           String @id @default(uuid()) @db.Uuid\n  userId       String @unique @db.Uuid\n  totalXP      Int    @default(0)\n  currentLevel Int    @default(1)\n  currentRank  String @default(\"tech_jjc\")\n\n  postsCount     Int @default(0)\n  commentsCount  Int @default(0)\n  likesReceived  Int @default(0)\n  likesGiven     Int @default(0)\n  totalReferrals Int @default(0)\n\n  loginStreak   Int       @default(0)\n  longestStreak Int       @default(0)\n  lastLoginDate DateTime?\n\n  badgesEarned        String[] @default([])\n  challengesCompleted Int      @default(0)\n\n  weeklyXP    Int @default(0)\n  monthlyXP   Int @default(0)\n  weeklyRank  Int @default(0)\n  monthlyRank Int @default(0)\n\n  lastActiveAt DateTime @default(now())\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  snapshots LeaderboardSnapshot[]\n\n  @@index([totalXP(sort: Desc)])\n  @@index([weeklyXP(sort: Desc)])\n}\n\nmodel LeaderboardSnapshot {\n  id          String       @id @default(uuid()) @db.Uuid\n  userId      String       @db.Uuid\n  rank        Int\n  totalXP     Int\n  type        SnapshotType // ALL_TIME, WEEKLY, MONTHLY\n  userStatsId String       @db.Uuid\n\n  createdAt DateTime @default(now())\n\n  userStats UserStats @relation(fields: [userStatsId], references: [id])\n\n  @@index([userId, type])\n  @@index([createdAt(sort: Desc)])\n}\n\nmodel Referral {\n  id             String         @id @default(uuid()) @db.Uuid\n  referrerId     String         @db.Uuid\n  referredId     String         @db.Uuid\n  referralCode   String         @unique\n  status         ReferralStatus @default(PENDING)\n  expiresAt      DateTime\n  completedAt    DateTime?\n  rewardsClaimed Boolean        @default(false)\n  referrerReward Int            @default(25)\n  referredReward Int            @default(15)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([referrerId, status])\n  @@index([referredId, status])\n}\n\n// --- 3.7 Missions & Challenges ---\n\nmodel Mission {\n  id               String          @id @default(uuid()) @db.Uuid\n  title            String          @db.VarChar(100)\n  description      String          @db.VarChar(500)\n  type             MissionType\n  difficulty       Difficulty\n  duration         MissionDuration\n  steps            Json // Array of { id, title, description, target, metric }\n  rewards          Json // { xp, badge?, title?, specialReward? }\n  prerequisites    String[]        @default([])\n  isActive         Boolean         @default(true)\n  participantCount Int             @default(0)\n  completionCount  Int             @default(0)\n  createdById      String          @db.Uuid\n  aiGenerated      Boolean         @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  progress MissionProgress[]\n\n  @@index([isActive, type, difficulty])\n}\n\nmodel MissionProgress {\n  id             String         @id @default(uuid()) @db.Uuid\n  userId         String         @db.Uuid\n  missionId      String         @db.Uuid\n  status         ProgressStatus @default(ACTIVE)\n  currentStep    Int            @default(0)\n  stepsCompleted String[]       @default([])\n  progress       Json?          @default(\"[]\")\n  startedAt      DateTime       @default(now())\n  completedAt    DateTime?\n  xpEarned       Int            @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  mission Mission @relation(fields: [missionId], references: [id])\n\n  @@unique([userId, missionId])\n  @@index([userId, status])\n}\n\nmodel WeeklyChallenge {\n  id                   String              @id @default(uuid()) @db.Uuid\n  title                String              @db.VarChar(100)\n  description          String              @db.VarChar(500)\n  type                 ChallengeType\n  difficulty           ChallengeDifficulty\n  requirements         Json // { target, metric, description }\n  rewards              Json // { xp, badge?, title? }\n  startDate            DateTime\n  endDate              DateTime\n  isActive             Boolean             @default(true)\n  participantCount     Int                 @default(0)\n  completionCount      Int                 @default(0)\n  firstCompletionBonus Int                 @default(10)\n  createdById          String              @db.Uuid\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  participations ChallengeParticipation[]\n\n  @@index([isActive, startDate, endDate])\n}\n\nmodel ChallengeParticipation {\n  id                String         @id @default(uuid()) @db.Uuid\n  userId            String         @db.Uuid\n  challengeId       String         @db.Uuid\n  status            ProgressStatus @default(ACTIVE)\n  progress          Int            @default(0)\n  completedAt       DateTime?\n  isFirstCompletion Boolean        @default(false)\n  xpEarned          Int            @default(0)\n  submissionData    Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  challenge WeeklyChallenge @relation(fields: [challengeId], references: [id])\n\n  @@unique([userId, challengeId])\n}\n\n// --- 3.8 Projects, Knowledge, Notifications, Reports, Analytics ---\n\nmodel Project {\n  id            String        @id @default(uuid()) @db.Uuid\n  title         String        @db.VarChar(100)\n  description   String        @db.Text\n  authorId      String        @db.Uuid\n  technologies  String[]      @default([])\n  githubUrl     String?\n  liveUrl       String?\n  images        String[]      @default([])\n  openPositions Json?         @default(\"[]\") // Array of position objects\n  status        ProjectStatus @default(IN_PROGRESS)\n  visibility    Visibility    @default(PUBLIC)\n  views         Int           @default(0)\n  featured      Boolean       @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  author    User       @relation(fields: [authorId], references: [id])\n  auditLogs AuditLog[] @relation(\"ProjectAudit\")\n\n  @@index([authorId, createdAt(sort: Desc)])\n  @@index([featured, createdAt(sort: Desc)])\n}\n\nmodel KnowledgeEntry {\n  id          String            @id @default(uuid()) @db.Uuid\n  title       String            @db.VarChar(200)\n  technology  String\n  category    KnowledgeCategory\n  content     String            @db.Text\n  codeExample String?           @db.Text\n  tags        String[]          @default([])\n  authorId    String            @db.Uuid\n  likesCount  Int               @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([technology, createdAt(sort: Desc)])\n  @@index([title, content]) // For basic text search\n}\n\nmodel Notification {\n  id          String           @id @default(uuid()) @db.Uuid\n  recipientId String           @db.Uuid\n  senderId    String           @db.Uuid\n  type        NotificationType\n  title       String           @db.VarChar(100)\n  message     String           @db.VarChar(500)\n  relatedId   String?          @db.Uuid // Generic FK for post/project/comment\n  relatedType String? // \"post\" | \"project\" | \"comment\"\n  read        Boolean          @default(false)\n  actionUrl   String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  recipient User @relation(\"RecipientNotifications\", fields: [recipientId], references: [id])\n  sender    User @relation(\"SenderNotifications\", fields: [senderId], references: [id])\n\n  @@index([recipientId, createdAt(sort: Desc)])\n  @@index([recipientId, read])\n}\n\nmodel Report {\n  id             String        @id @default(uuid()) @db.Uuid\n  reporterId     String        @db.Uuid\n  reportedPostId String        @db.Uuid\n  reportedUserId String        @db.Uuid\n  reason         ReportReason\n  description    String?       @db.VarChar(500)\n  status         ReportStatus  @default(PENDING)\n  reviewedById   String?       @db.Uuid\n  reviewedAt     DateTime?\n  action         ReportAction?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n}\n\nmodel Activity {\n  id          String       @id @default(uuid()) @db.Uuid\n  userId      String       @db.Uuid\n  type        ActivityType\n  description String       @db.VarChar(500)\n  metadata    Json?        @default(\"{}\")\n  xpEarned    Int          @default(0)\n\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@index([userId, createdAt(sort: Desc)])\n}\n\nmodel View {\n  id        String  @id @default(uuid()) @db.Uuid\n  postId    String  @db.Uuid\n  userId    String? @db.Uuid\n  ipAddress String\n  userAgent String?\n\n  createdAt DateTime @default(now())\n\n  post Post @relation(fields: [postId], references: [id], onDelete: Cascade)\n\n  @@unique([postId, userId, ipAddress])\n  @@index([postId])\n}\n\nmodel Feedback {\n  id            String         @id @default(uuid()) @db.Uuid\n  userId        String         @db.Uuid\n  type          FeedbackType\n  subject       String         @db.VarChar(200)\n  description   String         @db.Text\n  rating        Int?\n  status        FeedbackStatus @default(OPEN)\n  commentsCount Int            @default(0)\n  solvedById    String?        @db.Uuid\n  solvedAt      DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  comments FeedbackComment[]\n}\n\nmodel FeedbackComment {\n  id             String  @id @default(uuid()) @db.Uuid\n  feedbackId     String  @db.Uuid\n  userId         String  @db.Uuid\n  content        String  @db.VarChar(1000)\n  isAdminComment Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  feedback Feedback @relation(fields: [feedbackId], references: [id], onDelete: Cascade)\n}\n\nmodel BotAccount {\n  id               String         @id @default(uuid()) @db.Uuid\n  userId           String         @db.Uuid\n  isActive         Boolean        @default(true)\n  personality      BotPersonality @default(FRIENDLY)\n  commentFrequency Int            @default(5)\n  lastActive       DateTime       @default(now())\n  totalComments    Int            @default(0)\n  totalReplies     Int            @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  activities BotActivity[]\n}\n\nmodel BotActivity {\n  id           String    @id @default(uuid()) @db.Uuid\n  botAccountId String    @db.Uuid\n  postId       String    @db.Uuid\n  commentId    String?   @db.Uuid\n  action       BotAction\n  content      String    @db.Text\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  botAccount BotAccount @relation(fields: [botAccountId], references: [id])\n\n  @@index([botAccountId, postId])\n}\n\nmodel AiLog {\n  id            String    @id @default(uuid()) @db.Uuid\n  service       AiService // MISTRAL, GEMINI\n  aiModel       String\n  taskType      String\n  inputLength   Int\n  outputSummary String    @db.VarChar(500)\n  userId        String?   @db.Uuid\n  success       Boolean   @default(true)\n  errorMessage  String?\n  executionTime Int // ms\n  createdAt     DateTime  @default(now())\n\n  @@index([service, taskType])\n  @@index([userId])\n  @@index([createdAt(sort: Desc)])\n}\n\nmodel AuditLog {\n  id         String  @id @default(uuid()) @db.Uuid\n  adminId    String  @db.Uuid\n  action     String // e.g., \"USER_BAN\", \"POST_DELETE\"\n  targetType String // \"USER\", \"POST\", \"PROJECT\"\n  targetId   String  @db.Uuid\n  reason     String? @db.VarChar(500)\n  metadata   Json?\n\n  createdAt DateTime @default(now())\n\n  // Relations (Optional back-references if needed)\n  post    Post?    @relation(\"PostAudit\", fields: [targetId], references: [id], onDelete: SetNull, map: \"AuditLog_Post_fkey\")\n  project Project? @relation(\"ProjectAudit\", fields: [targetId], references: [id], onDelete: SetNull, map: \"AuditLog_Project_fkey\")\n\n  @@index([adminId])\n  @@index([targetId])\n}\n\n// Enums\n\nenum UserRole {\n  USER\n  MODERATOR\n  ADMIN\n  ANALYTICS\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum UserType {\n  STUDENT\n  DEVELOPER\n  DESIGNER\n  ENTREPRENEUR\n  OTHER\n}\n\nenum ExperienceLevel {\n  BEGINNER\n  INTERMEDIATE\n  ADVANCED\n  EXPERT\n}\n\nenum RegistrationSource {\n  ORGANIC\n  REFERRAL\n  SOCIAL\n  DIRECT\n  EMAIL\n  SEARCH\n}\n\nenum PostStatus {\n  PENDING_REVIEW\n  ACTIVE\n  ARCHIVED\n  BLOCKED\n}\n\nenum MediaType {\n  IMAGE\n  VIDEO\n}\n\nenum LikeTargetType {\n  POST\n  COMMENT\n}\n\nenum BlockReason {\n  SPAM\n  HARASSMENT\n  INAPPROPRIATE\n  OTHER\n}\n\nenum MessageType {\n  TEXT\n  IMAGE\n  FILE\n}\n\nenum CommunityCategory {\n  FRONTEND\n  BACKEND\n  MOBILE\n  DEVOPS\n  DATA\n  AI\n  BLOCKCHAIN\n  GENERAL\n}\n\nenum CommunityMemberRole {\n  MEMBER\n  MODERATOR\n  CREATOR\n}\n\nenum XpEventType {\n  DAILY_LOGIN\n  POST_CREATION\n  COMMENT_CREATION\n  LIKE_GIVEN\n  LIKE_RECEIVED\n  FIRST_POST\n  FIRST_COMMENT\n  POLL_INTERACTION\n  BADGE_EARNED\n  LEVEL_UP\n  MODERATOR_ACTION_BONUS\n  REFERRAL_SUCCESS\n  REFERRAL_BONUS\n  EMAIL_VERIFIED\n  USER_FOLLOWED\n  CHALLENGE_COMPLETION\n  DAILY_CHALLENGE\n  QUALITY_CONTENT\n  ADMIN_ADJUSTMENT\n}\n\nenum SnapshotType {\n  ALL_TIME\n  WEEKLY\n  MONTHLY\n}\n\nenum ReferralStatus {\n  PENDING\n  COMPLETED\n  EXPIRED\n}\n\nenum MissionType {\n  SOCIAL\n  CONTENT\n  ENGAGEMENT\n  LEARNING\n  ACHIEVEMENT\n}\n\nenum MissionDuration {\n  DAILY\n  WEEKLY\n  MONTHLY\n  PERMANENT\n}\n\nenum Difficulty {\n  BEGINNER\n  INTERMEDIATE\n  ADVANCED\n  EXPERT\n}\n\nenum ProgressStatus {\n  ACTIVE\n  COMPLETED\n  PAUSED\n  FAILED\n}\n\nenum ChallengeType {\n  POST_CREATION\n  ENGAGEMENT\n  COMMUNITY\n  LEARNING\n  CREATIVE\n}\n\nenum ChallengeDifficulty {\n  EASY\n  MEDIUM\n  HARD\n}\n\nenum ProjectStatus {\n  PLANNING\n  IN_PROGRESS\n  COMPLETED\n  ON_HOLD\n}\n\nenum Visibility {\n  PUBLIC\n  PRIVATE\n}\n\nenum KnowledgeCategory {\n  TUTORIAL\n  CODE_SNIPPET\n  BEST_PRACTICE\n  TROUBLESHOOTING\n  CONFIGURATION\n  API_REFERENCE\n  COMMAND_REFERENCE\n  QUICK_TIP\n}\n\nenum NotificationType {\n  LIKE\n  COMMENT\n  FOLLOW\n  PROJECT_LIKE\n  MENTION\n  SYSTEM\n  XP_OVERTAKE\n  XP_OVERTAKEN\n}\n\nenum ReportReason {\n  SPAM\n  HARASSMENT\n  INAPPROPRIATE\n  MISINFORMATION\n  COPYRIGHT\n  OTHER\n}\n\nenum ReportStatus {\n  PENDING\n  REVIEWED\n  RESOLVED\n  DISMISSED\n}\n\nenum ReportAction {\n  NONE\n  WARNING\n  POST_REMOVED\n  USER_SUSPENDED\n  USER_BANNED\n}\n\nenum ActivityType {\n  POST_CREATED\n  COMMENT_CREATED\n  LIKE_GIVEN\n  USER_FOLLOWED\n  BADGE_EARNED\n  LEVEL_UP\n  QUALITY_BONUS\n}\n\nenum FeedbackType {\n  BUG\n  FEATURE\n  GENERAL\n  IMPROVEMENT\n}\n\nenum FeedbackStatus {\n  OPEN\n  IN_PROGRESS\n  SOLVED\n}\n\nenum AiService {\n  MISTRAL\n  GEMINI\n}\n\nenum BotPersonality {\n  FRIENDLY\n  TECHNICAL\n  CASUAL\n  PROFESSIONAL\n}\n\nenum BotAction {\n  COMMENT\n  REPLY\n}\n"
}

